import {
  Archive,
  File as FileIcon,
  FileText,
  Image,
  Music,
  RefreshCw,
  Video,
} from "lucide-react";

type Material = {
  id?: string;
  name?: string;
  filename?: string;
  path?: string;
  url?: string;
  type?: string;
  kind?: string;
  size?: number | string;
  modifiedAt?: string;
  mtime?: string;
  createdAt?: string;
};

const listVariants = {
  hidden: { opacity: 1 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.055,
      delayChildren: 0.05,
    },
  },
};

const cardVariants = {
  hidden: { opacity: 0, y: 16, scale: 0.98 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.28, ease: [0.16, 1, 0.3, 1] },
  },
};

function normalizeMaterials(payload: unknown): Material[] {
  if (Array.isArray(payload)) return payload as Material[];

  if (payload && typeof payload === "object") {
    const data = payload as Record<string, unknown>;

    if (Array.isArray(data.materials)) return data.materials as Material[];
    if (Array.isArray(data.files)) return data.files as Material[];
    if (Array.isArray(data.items)) return data.items as Material[];
    if (Array.isArray(data.data)) return data.data as Material[];
  }

  return [];
}

function getMaterialName(material: Material) {
  return material.name || material.filename || material.path?.split("/").pop() || "未命名素材";
}

function getMaterialKey(material: Material, index: number) {
  return material.id || material.path || material.url || `${getMaterialName(material)}-${index}`;
}

function getExtension(material: Material) {
  const name = getMaterialName(material).toLowerCase();
  const ext = name.includes(".") ? name.split(".").pop() || "" : "";
  return ext;
}

function getMaterialCategory(material: Material) {
  const rawType = `${material.type || ""} ${material.kind || ""}`.toLowerCase();
  const ext = getExtension(material);

  if (rawType.includes("image") || ["jpg", "jpeg", "png", "gif", "webp", "svg"].includes(ext)) {
    return "image";
  }

  if (rawType.includes("video") || ["mp4", "mov", "avi", "mkv", "webm"].includes(ext)) {
    return "video";
  }

  if (rawType.includes("audio") || ["mp3", "wav", "aac", "flac", "m4a", "ogg"].includes(ext)) {
    return "audio";
  }

  if (["txt", "md", "json", "csv", "doc", "docx", "pdf"].includes(ext)) {
    return "document";
  }

  if (["zip", "rar", "7z", "tar", "gz"].includes(ext)) {
    return "archive";
  }

  return "file";
}

function getMaterialIcon(material: Material) {
  const category = getMaterialCategory(material);
  const className = "size-5";

  switch (category) {
    case "image":
      return <Image className={`${className} text-[var(--accent)]`} />;
    case "video":
      return <Video className={`${className} text-[var(--info)]`} />;
    case "audio":
      return <Music className={`${className} text-[var(--success)]`} />;
    case "document":
      return <FileText className={`${className} text-[var(--warning)]`} />;
    case "archive":
      return <Archive className={`${className} text-[var(--text-muted)]`} />;
    default:
      return <FileIcon className={`${className} text-[var(--text-muted)]`} />;
  }
}

function formatSize(size?: number | string) {
  if (size === undefined || size === null || size === "") return "未知大小";

  const value = typeof size === "string" ? Number(size) : size;
  if (!Number.isFinite(value)) return String(size);

  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
  if (value < 1024 * 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MB`;

  return `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`;
}

function formatTime(material: Material) {
  const value = material.modifiedAt || material.mtime || material.createdAt;
  if (!value) return "暂无时间";

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;

  return date.toLocaleString("zh-CN", {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function SkeletonGrid() {
  return (
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
      {Array.from({ length: 6 }).map((_, index) => (
        <div
          key={index}
          className="rounded-2xl border border-[var(--border)] bg-[var(--bg-raised)] p-4"
        >
          <div className="animate-pulse space-y-4">
            <div className="h-11 w-11 rounded-xl bg-[var(--border)]" />
            <div className="space-y-2">
              <div className="h-4 w-3/4 rounded-full bg-[var(--border)]" />
              <div className="h-3 w-1/2 rounded-full bg-[var(--border)]" />
            </div>
            <div className="h-9 rounded-xl bg-[var(--border)]" />
          </div>
        </div>
      ))}
    </div>
  );
}

