    const response = await fetch("/api/materials?dir=runtime/outputs");

    if (!response.ok) {
      throw new Error(`产出文件读取失败：${response.status}`);
    }

    const payload = await response.json();
    setOutputs(normalizeMaterials(payload));
  }, []);

