      {
        label: "产出文件",
        value: `${outputs.length} 个`,
        icon: Archive,
        tone: "text-[var(--text-primary)]",
      },
      {
        label: "当前任务",
        value: pipelineStatus?.current || pipelineStatus?.currentFile || "暂无任务",
        icon: Camera,
        tone: "text-[var(--text-primary)]",
      },
    ],
    [outputs.length, pipelineStatus],
  );

