            <div className="absolute bottom-4 left-4 right-4 flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--bg-raised)] px-4 py-3">
              <div>
                <p className="text-xs text-[var(--text-muted)]">当前状态</p>
                <p className={`mt-1 text-sm font-semibold ${getStatusTone(pipelineStatus)}`}>
                  {getStatusText(pipelineStatus)}
