        <section className="rounded-3xl border border-[var(--border)] bg-[var(--bg-raised)] p-4 md:p-5">
          <div className="mb-5 flex items-start justify-between gap-4">
            <div>
              <h2 className="text-base font-semibold text-[var(--text-primary)]">实时产出</h2>
              <p className="mt-1 text-sm text-[var(--text-muted)]">实时管线产出文件</p>
            </div>

            <div className="rounded-full border border-[var(--border)] px-3 py-1 text-xs text-[var(--text-muted)]">
              {outputs.length} 个文件
            </div>
