              {outputs.map((material, index) => (
                <motion.div
                  key={getMaterialKey(material, index)}
                  variants={itemVariants}
                  whileHover={{ x: 3 }}
                  className="cursor-pointer rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] p-4 transition hover:border-[var(--border-strong)]"
                >
                  <div className="flex items-center gap-3">
                    <div className="flex size-11 shrink-0 items-center justify-center rounded-xl border border-[var(--border)] bg-[var(--bg-raised)]">
                      {getMaterialIcon(material)}
