import { useCallback, useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import {
  Activity,
  HardDrive,
  Monitor,
  RefreshCw,
  Server,
  Wifi,
} from "lucide-react";

type PipelineStatus = {
  running?: boolean;
  status?: string;
  state?: string;
  message?: string;
  current?: string;
  progress?: number;
  updatedAt?: string;
};

type HealthStatus = {
  ok?: boolean;
  status?: string;
  message?: string;
  uptime?: number;
  version?: string;
  service?: string;
};

type LocalSettings = {
  pollInterval: "3" | "5" | "10" | "30";
  obsWebSocketUrl: string;
  autoStartPipeline: boolean;
};

const STORAGE_KEY = "phs-control-settings";

const defaultSettings: LocalSettings = {
  pollInterval: "5",
  obsWebSocketUrl: "ws://localhost:4455",
  autoStartPipeline: false,
};

const listVariants = {
  hidden: { opacity: 1 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.06,
      delayChildren: 0.05,
    },
  },
};

const cardVariants = {
  hidden: { opacity: 0, y: 16, scale: 0.98 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.28, ease: [0.16, 1, 0.3, 1] },
  },
};

function loadLocalSettings(): LocalSettings {
  if (typeof window === "undefined") return defaultSettings;

  try {
    const cached = window.localStorage.getItem(STORAGE_KEY);
    if (!cached) return defaultSettings;

    const parsed = JSON.parse(cached) as Partial<LocalSettings>;

    return {
      pollInterval: parsed.pollInterval || defaultSettings.pollInterval,
      obsWebSocketUrl: parsed.obsWebSocketUrl || defaultSettings.obsWebSocketUrl,
      autoStartPipeline:
        typeof parsed.autoStartPipeline === "boolean"
          ? parsed.autoStartPipeline
          : defaultSettings.autoStartPipeline,
    };
  } catch {
    return defaultSettings;
  }
}

function getPipelineText(status: PipelineStatus | null) {
  if (!status) return "等待状态";
  if (status.running) return "运行中";
  return status.state || status.status || "待启动";
}

function getHealthText(health: HealthStatus | null) {
  if (!health) return "等待状态";
  if (health.ok || health.status === "ok" || health.status === "healthy") return "正常";
  return health.status || "未知";
}

function formatUptime(seconds?: number) {
  if (typeof seconds !== "number" || !Number.isFinite(seconds)) return "--";

  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);

  if (hours > 0) return `${hours} 小时 ${minutes} 分钟`;
  return `${minutes} 分钟`;
}

export default function SettingsPage() {
  const [settings, setSettings] = useState<LocalSettings>(() => loadLocalSettings());
  const [pipelineStatus, setPipelineStatus] = useState<PipelineStatus | null>(null);
  const [healthStatus, setHealthStatus] = useState<HealthStatus | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdatedAt, setLastUpdatedAt] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const saveSettings = useCallback((nextSettings: LocalSettings) => {
    setSettings(nextSettings);

    if (typeof window !== "undefined") {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(nextSettings));
    }
  }, []);

  const updateSetting = <Key extends keyof LocalSettings>(key: Key, value: LocalSettings[Key]) => {
    saveSettings({
      ...settings,
      [key]: value,
    });
  };

  const refreshStatus = useCallback(async () => {
    setRefreshing(true);
    setError(null);

    try {
      const [pipelineResult, healthResult] = await Promise.all([
        fetch("/api/pipeline/status"),
        fetch("/api/health"),
      ]);

      if (!pipelineResult.ok) {
        throw new Error(`管线状态读取失败：${pipelineResult.status}`);
      }

      if (!healthResult.ok) {
        throw new Error(`健康状态读取失败：${healthResult.status}`);
      }

      const pipelinePayload = await pipelineResult.json();
      const healthPayload = await healthResult.json();

      setPipelineStatus(pipelinePayload as PipelineStatus);
      setHealthStatus(healthPayload as HealthStatus);
      setLastUpdatedAt(
        new Date().toLocaleString("zh-CN", {
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        }),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "系统状态读取失败");
    } finally {
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    refreshStatus();

    const timer = window.setInterval(() => {
      refreshStatus();
    }, Number(settings.pollInterval) * 1000);

    return () => window.clearInterval(timer);
  }, [refreshStatus, settings.pollInterval]);

  const statusCards = useMemo(
    () => [
      {
        label: "API 服务",
        value: getHealthText(healthStatus),
        helper: healthStatus?.message || healthStatus?.service || "后端健康检查",
        icon: Server,
        tone:
          healthStatus?.ok || healthStatus?.status === "ok" || healthStatus?.status === "healthy"
            ? "text-[var(--success)]"
            : "text-[var(--text-muted)]",
      },
      {
        label: "素材管线",
        value: getPipelineText(pipelineStatus),
        helper: pipelineStatus?.message || pipelineStatus?.current || "管线状态监控",
        icon: Activity,
        tone: pipelineStatus?.running ? "text-[var(--success)]" : "text-[var(--text-muted)]",
      },
      {
        label: "运行时间",
        value: formatUptime(healthStatus?.uptime),
        helper: healthStatus?.version ? `版本 ${healthStatus.version}` : "服务启动后累计时间",
        icon: HardDrive,
        tone: "text-[var(--text-primary)]",
      },
    ],
    [healthStatus, pipelineStatus],
  );

  return (
    <div className="space-y-6">
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.32 }}
        className="rounded-3xl border border-[var(--border)] bg-[var(--bg-raised)] p-5 shadow-sm md:p-6"
      >
        <div className="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between">
          <div className="space-y-2">
            <div className="inline-flex items-center gap-2 rounded-full border border-[var(--border)] px-3 py-1 text-xs font-medium text-[var(--text-muted)]">
              <Monitor className="size-3.5" />
              系统设置
            </div>
            <div>
              <h1 className="text-2xl font-semibold tracking-tight text-[var(--text-primary)] md:text-3xl">
                设置
              </h1>
              <p className="mt-2 max-w-2xl text-sm leading-6 text-[var(--text-body)]">
                系统状态监控与配置
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={refreshStatus}
            disabled={refreshing}
            className="inline-flex items-center justify-center gap-2 rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] px-4 py-2.5 text-sm font-medium text-[var(--text-primary)] transition hover:border-[var(--border-strong)] hover:bg-[var(--accent-hover)] disabled:cursor-not-allowed disabled:opacity-60"
          >
            <RefreshCw className={`size-4 ${refreshing ? "animate-spin" : ""}`} />
            刷新状态
          </button>
        </div>
      </motion.section>

      {error ? (
        <div className="rounded-2xl border border-[var(--danger)] bg-[var(--bg-raised)] p-4 text-sm text-[var(--danger)]">
          {error}
        </div>
      ) : null}

      <motion.section
        variants={listVariants}
        initial="hidden"
        animate="visible"
        className="grid gap-4 lg:grid-cols-3"
      >
        {statusCards.map((item) => {
          const Icon = item.icon;

          return (
            <motion.div
              key={item.label}
              variants={cardVariants}
              className="rounded-2xl border border-[var(--border)] bg-[var(--bg-raised)] p-4"
            >
              <div className="flex items-start justify-between gap-4">
                <div className="min-w-0">
                  <p className="text-sm text-[var(--text-muted)]">{item.label}</p>
                  <p className={`mt-2 truncate text-xl font-semibold ${item.tone}`}>
                    {item.value}
                  </p>
                  <p className="mt-2 truncate text-xs text-[var(--text-muted)]">{item.helper}</p>
                </div>

                <div className="flex size-11 shrink-0 items-center justify-center rounded-xl border border-[var(--border)] bg-[var(--bg-page)]">
                  <Icon className="size-5 text-[var(--text-muted)]" />
                </div>
              </div>
            </motion.div>
          );
        })}
      </motion.section>

      <div className="grid gap-6 xl:grid-cols-[0.95fr_1.05fr]">
        <motion.section
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.34, delay: 0.04 }}
          className="rounded-3xl border border-[var(--border)] bg-[var(--bg-raised)] p-5"
        >
          <div className="mb-5">
            <h2 className="text-base font-semibold text-[var(--text-primary)]">基础配置</h2>
            <p className="mt-1 text-sm text-[var(--text-muted)]">
              配置项保存在本地浏览器 localStorage 中。
            </p>
          </div>

          <div className="space-y-5">
            <label className="block">
              <span className="text-sm font-medium text-[var(--text-primary)]">轮询间隔</span>
              <select
                value={settings.pollInterval}
                onChange={(event) =>
                  updateSetting("pollInterval", event.target.value as LocalSettings["pollInterval"])
                }
                className="mt-2 w-full rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] px-4 py-3 text-sm text-[var(--text-primary)] outline-none transition focus:border-[var(--accent)] focus:ring-2 focus:ring-[var(--accent)]"
              >
                <option value="3">3 秒</option>
                <option value="5">5 秒</option>
                <option value="10">10 秒</option>
                <option value="30">30 秒</option>
              </select>
            </label>

            <label className="block">
              <span className="text-sm font-medium text-[var(--text-primary)]">
                OBS WebSocket 地址
              </span>
              <div className="mt-2 flex items-center gap-3 rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] px-4 py-3 transition focus-within:border-[var(--accent)] focus-within:ring-2 focus-within:ring-[var(--accent)]">
                <Wifi className="size-4 shrink-0 text-[var(--text-muted)]" />
                <input
                  value={settings.obsWebSocketUrl}
                  onChange={(event) => updateSetting("obsWebSocketUrl", event.target.value)}
                  placeholder="ws://localhost:4455"
                  className="w-full bg-transparent text-sm text-[var(--text-primary)] outline-none placeholder:text-[var(--text-muted)]"
                />
              </div>
            </label>

            <div className="rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] p-4">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm font-medium text-[var(--text-primary)]">自动启动管线</p>
                  <p className="mt-1 text-xs leading-5 text-[var(--text-muted)]">
                    打开页面后自动尝试启动素材处理管线。
                  </p>
                </div>

                <button
                  type="button"
                  role="switch"
                  aria-checked={settings.autoStartPipeline}
                  onClick={() => updateSetting("autoStartPipeline", !settings.autoStartPipeline)}
                  className={`relative h-7 w-12 shrink-0 rounded-full border transition ${
                    settings.autoStartPipeline
                      ? "border-[var(--accent)] bg-[var(--accent)]"
                      : "border-[var(--border-strong)] bg-[var(--bg-raised)]"
                  }`}
                >
                  <span
                    className={`absolute top-1 size-5 rounded-full bg-[var(--bg-deep)] transition ${
                      settings.autoStartPipeline ? "left-6" : "left-1"
                    }`}
                  />
                </button>
              </div>
            </div>
          </div>
        </motion.section>

        <motion.section
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.34, delay: 0.08 }}
          className="rounded-3xl border border-[var(--border)] bg-[var(--bg-raised)] p-5"
        >
          <div className="mb-5 flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <h2 className="text-base font-semibold text-[var(--text-primary)]">实时状态</h2>
              <p className="mt-1 text-sm text-[var(--text-muted)]">
                根据当前轮询间隔自动刷新系统状态。
              </p>
            </div>

            <div className="rounded-full border border-[var(--border)] px-3 py-1 text-xs text-[var(--text-muted)]">
              {lastUpdatedAt ? `更新于 ${lastUpdatedAt}` : "尚未更新"}
            </div>
          </div>

          <div className="space-y-3">
            <div className="rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] p-4">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm text-[var(--text-muted)]">健康检查</p>
                  <p className="mt-1 text-base font-semibold text-[var(--text-primary)]">
                    {getHealthText(healthStatus)}
                  </p>
                </div>
                <Server className="size-5 text-[var(--text-muted)]" />
              </div>
              <p className="mt-3 text-xs leading-5 text-[var(--text-muted)]">
                {healthStatus?.message || "等待 /api/health 返回服务状态。"}
              </p>
            </div>

            <div className="rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] p-4">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm text-[var(--text-muted)]">管线状态</p>
                  <p className="mt-1 text-base font-semibold text-[var(--text-primary)]">
                    {getPipelineText(pipelineStatus)}
                  </p>
                </div>
                <Activity className="size-5 text-[var(--text-muted)]" />
              </div>

              <div className="mt-4 h-2 overflow-hidden rounded-full bg-[var(--border)]">
                <div
                  className="h-full rounded-full bg-[var(--accent)] transition-all"
                  style={{
                    width:
                      typeof pipelineStatus?.progress === "number"
                        ? `${Math.min(Math.max(pipelineStatus.progress, 0), 100)}%`
                        : pipelineStatus?.running
                          ? "48%"
                          : "0%",
                  }}
                />
              </div>

              <p className="mt-3 text-xs leading-5 text-[var(--text-muted)]">
                {pipelineStatus?.message || pipelineStatus?.current || "等待管线状态更新。"}
              </p>
            </div>

            <div className="rounded-2xl border border-[var(--border)] bg-[var(--bg-page)] p-4">
              <p className="text-sm font-medium text-[var(--text-primary)]">当前配置快照</p>
              <div className="mt-4 grid gap-3 text-xs sm:grid-cols-2">
                <div className="rounded-xl border border-[var(--border)] bg-[var(--bg-raised)] px-3 py-2">
                  <p className="text-[var(--text-muted)]">轮询间隔</p>
                  <p className="mt-1 font-medium text-[var(--text-primary)]">
                    {settings.pollInterval} 秒
                  </p>
                </div>
                <div className="rounded-xl border border-[var(--border)] bg-[var(--bg-raised)] px-3 py-2">
                  <p className="text-[var(--text-muted)]">自动启动</p>
                  <p className="mt-1 font-medium text-[var(--text-primary)]">
                    {settings.autoStartPipeline ? "已开启" : "已关闭"}
                  </p>
                </div>
                <div className="rounded-xl border border-[var(--border)] bg-[var(--bg-raised)] px-3 py-2 sm:col-span-2">
                  <p className="text-[var(--text-muted)]">OBS WebSocket</p>
                  <p className="mt-1 truncate font-medium text-[var(--text-primary)]">
                    {settings.obsWebSocketUrl}
                  </p>
